[299]={"Desvendando o passado",{"O Prospector Whelgar quer que você revire o sítio de escavação em busca dos 4 fragmentos perdidos da tabuleta: Ados, Modr, Golm e Neru."}},
[301]={"Apresente-se a Altaforja",{"Entregue o Relatório de Progresso de Bandaferro para o Prospector Lançatroz."}},
[302]={"Pólvora para Bandaferro",{"Fale com Jern Elmocorno em Thelsamar."}},
[303]={"A guerra dos Ferro Negro",{"Rocio Garmason, de Dun Modr, quer que você mate 15 Anões Ferro Negro, 5 Escavadores Ferro Negro, 5 Sabotadores Ferro Negro e 5 Demolidores Ferro Negro."}},
[304]={"Uma tarefa cruel",{"Mate Balgaras, o Asqueroso e leve a orelha dele para Trançalonga, o Austero, que está do lado de fora de Dun Modr."}},
[305]={"Em busca da equipe de escavação",{"Tarrel Tecepedra quer que você viaje até o Sítio de Escavação e contate Marina Tecepedra."}},
[306]={"Em busca da equipe de escavação",{"Leve o bilhete de Marina para Tarrel Tecepedra."}},
[307]={"Patas nojentas",{"Vá até a Mina da Prata e recolha 4 cargas de Equipamento de Mineração.","","Fale novamente com o Montanhista Lançatroz."}},
[308]={"Distraindo Jarven",nil},
[309]={"Em defesa do carregamento",{"Garanta que Miran e o carregamento cheguem ao sítio de escavação, depois informe ao Prospector Bandaferro."}},
[310]={"A guerra das cervejas",{"Troque um barril de Cerveja do Trovão por um barril de Grogue Cervevada no porão da Destilaria Cervaforte, que fica em Kharanos."}},
[311]={"Fale novamente com Marleth",{"Entregue o barril de Cerveja do Trovão para Marleth Cervevada na Aldeia da Cevada."}},
[312]={"Por baixo da carne-seca",{"Pegue de volta a carne-seca do Tundra MacGrann do armário de carnes roubado, na caverna do Velho Barbafria."}},
[313]={"O Covil Cinzento",{"Colete 8 Crinas de Wendigo e leve-as para Piloto Marchapedra."}},
[314]={"Amarre sua cabra pois Ragash está solto",{"Rudra Ambarmanso quer que você mate Ragash e leve sua presa para ela no rancho dos carneiros."}},
[315]={"Em busca da cerveja perfeita",{"Entregue 6 ramos de Tremulerva para Rejold Cervevada na Aldeia da Cevada."}},
[317]={"Provisões para a Vaporeta",{"Junte 4 Nacos de Carne de Javali e 2 Pelames Grossos de Urso e entregue tudo para o Piloto Urrabolha na Garagem do Gradaço."}},
[318]={"Sempre-aceso",{"Pegue um barril de Sempre-aceso com o Rejold Cervevada na Aldeia da Cevada."}},
[319]={"Tudo pela Sempre-aceso",{"Mate 6 Ursos Garra de Gelo, 8 Rochetuscos Adultos e 8 Leopardos da Neve. Em seguida, fale novamente com Rejold Cervevada na Aldeia da Cevada."}},
[320]={"Fale novamente com Urrabolha",{"Entregue o barrilete de Sempre-aceso para o Piloto Urrabolha na Garagem do Gradaço."}},
[321]={"Ferro da Forja de Luz",{"Vasculhe os destroços do Águia-pesqueira no Pantanal."}},
[322]={"Braço abençoado",{"Leve o Caixote de Lingotes de Forja de Luz para Grimand Elmore em Ventobravo."}},
[323]={"Prova de valor",{"Mate 15 Saqueadores Descarnados, 3 Curandeiros Descarnados e 3 Guardadores Descarnados, e depois fale novamente com Noel."}},
[324]={"Os lingotes perdidos",{"Colete 5 Lingotes da Forja de Luz e fale novamente com Glorin Testaço no Pantanal."}},
[325]={"Com bala na agulha",{"Leve a Desgraça de Morbídio até Noel, na Floresta do Crepúsculo."}},
