[333]={"A lista de material do Fialho",{"Vá até a loja Ao Molde Moderno e entregue o Pedido de Tecido de Timóteo Fialho para Isabel Armarinho."}},
[334]={"Entrega para Antônio Armarinho",{"Vá até a Alfaiataria Galante, no Distrito dos Magos de Ventobravo, e entregue a caixa de costura para Antônio Armarinho."}},
[335]={"Uma bebida para poucos",{"O Malvino da Garra Preta quer que você lhe traga uma Lágrima de Tirsa da Vila Sombria e uma Raiz Almiscarada do Pantanal."}},
[336]={"Uma bebida para poucos",{"Sirva o Chope Garra Negra para o Barão Quadranilha na Sala de Audiência."}},
[337]={"Um velho livro de história",{"Devolva o livro \"A História de Ventobravo\" para a Biblioteca de Ventobravo."}},
[338]={"Grande Espinhaço: Veredas",{"Reúna as páginas que faltam do manuscrito de Grande Espinhaço: Veredas. Quando todos os quatro capítulos estiverem completos, devolva-os a Eucunha."}},
[339]={"Capítulo I",{"Leve as páginas 1, 4, 6 e 8 de Grande Espinhaço: Veredas, de Rosarães, até Eucunha de Clides para completar o Capítulo I."}},
[340]={"Capítulo II",{"Leve as páginas 10, 11, 14 e 16 de Grande Espinhaço: Veredas, de Rosarães, até Eucunha de Clides para completar o Capítulo II."}},
[341]={"Capítulo III",{"Leve as páginas 18, 20, 21 e 24 de Grande Espinhaço: Veredas, de Rosarães, até Eucunha de Clides para completar o Capítulo III."}},
[342]={"Capítulo IV",{"Leve as páginas 25, 26 e 27 de Grande Espinhaço: Veredas, de Rosarães, até Eucunha de Clides para completar o Capítulo IV."}},
[343]={"Falando sobre fortitude",{"Vá à Biblioteca Real na Bastilha Ventobravo e fale com Milton Resma. Ele pode encontrar para você o livro sobre metalurgia que o Irmão Kristoff precisa para o discurso."}},
[344]={"Irmão Paxeco",{"Fale com o Irmão Paxeco na Abadia de Vila Norte."}},
[345]={"Estoque de tinta",{"Fale com o Encarregado Oslow em Vila Plácida e peça-lhe Minério de Ferro Retibano."}},
[346]={"De novo com Kristoff",{"Fale novamente com Irmão Kristoff na Praça da Catedral. Dê a ele o livro Fadigas do Ferro."}},
[347]={"Minério Retibano",{"Colete 5 porções de Minério Retibano e leve-as para o Irmão Paxeco na biblioteca de Vila Norte."}},
[348]={"Febre da Selva do Espinhaço",{"Procure o Mandingueiro Unbagwa e faça-o evocar Mokk, o Selvagem. Leve o Coração de Mokk para Fino Algazarro."}},
[349]={"Febre da Selva do Espinhaço",nil},
[350]={"Procurando um velho amigo",{"Fale com Elling Trias em Ventobravo."}},
[351]={"Encontre OOX-17/TN!",{"Leve o transmissor de emergência até o robô teleguiado de Olhatorto."}},
[353]={"Entrega para Lançatroz",{"Entregue o Pacote para Lançatroz para o Montanhista Lançatroz em Loch Modan."}},
[354]={"Mortes na família",{"Obtenha os Restos Mortais de Gregor, os Restos Mortais de Nissa, os Restos Mortais de Timóteo para Eurico Palhares em Montalvo."}},
[355]={"Fale com Sevren",{"Fale com o Magistrado Sevren em Montalvo."}},
[356]={"Patrulha da retaguarda",{"Mate 8 Horrores Sangrentos e 8 Espíritos Errantes. Depois, apresente seu relatório a Linnea no acampamento."}},
[357]={"A identidade do lich",{"Leve o Grimório do Lich para Boanerges Stalactus na Cidade Baixa."}},
[358]={"Roubacovas",{"Mate Roubacovas Putricouro e Mestiços Putricouro.","","Leve 8 frascos de Linfa Embalsamadora para o Magistrado Sevren, em Montalvo."}},
