[4505]={"Poço da Corrupção",{"Colete uma amostra de água corrompida do poço lunar dos Sátiros Flamejade e leve-a para Winna Perícon no Posto Peçonha."}},
[4506]={"Dentes-de-sabre corrompidos",{"Leve o gatinho de Winna para o poço lunar corrompido, solte-o e depois o leve de volta para Winna.","","Quando retornar, clique no gato para deixá-lo com Winna."}},
[4507]={"O peão captura a rainha",{"Derrote a Rainha da Colmeia Gorishi assim que ela for atraída.","","Leve o Cérebro da Rainha Gorishi para o Alquimista Almofarrista em Geringontzan."}},
[4508]={"A calmaria que precede a tempestade",{"Leve o Relatório de Un'Goro do Almofarrista para Gracinha Forçânima em Darnassus."}},
[4509]={"A calmaria que precede a tempestade",{"Leve o Relatório de Un'Goro do Almofarrista para Zilzibin Tamborleiro em Orgrimmar."}},
[4510]={"A calmaria que precede a tempestade",{"Leve o Comprovante Bancário a Idriana no banco de Darnassus."}},
[4511]={"A calmaria que precede a tempestade",{"Leve o Comprovante Bancário para Karus, no banco de Orgrimmar."}},
[4512]={"Gosmologia",{"Entregue 6 Jarras de Gosma Amaldiçoada Cheias e 6 Jarras de Gosma Maculada Cheias para Laris Vagarroda em Altaforja."}},
[4513]={"Gosmologia",{"Leve 10 Jarras Cheias de Amostra Pura para Laris Vagarroda em Altaforja.","","Caso você não consiga encontrar as gosmas puras, peça mais pistas para o Laris."}},
[4521]={"Guardiões selvagens",{"Trull Ruinazar em Selva Maleva quer que você mate 15 Ferujas Furiosas e 15 Ferujas Maltrapilhas."}},
[4542]={"Mensagem para a Aldeia Vento Livre",{"Leve a Mensagem Urgente ao Vigia do Rochedo Chifre Longo na Aldeia Vento Livre."}},
