[6661]={"Ratos de porão",{"Capture 5 Ratos Correfundo com a Flauta do Pegador de Ratos. Conduza os ratos até o Monty. Não se esqueça de entregar a flauta quando terminar."}},
[6662]={"Espetinhos de... rato",{"Entregue a Caixa de Carne Duvidosa para Nipsy, na estação do Metrô Correfundo de Ventobravo."}},
[6681]={"Corvoforte, a mansão",{"Leve o Selo de Corvoforte para Fahrad na Mansão de Corvoforte, que fica oculta nas colinas de Eira dos Montes.","","Sua jornada testará sua sagacidade. Prepare-se."}},
[6701]={"Emblemas da Camarilha",nil},
[6721]={"O caminho do caçador",{"Fale com Dazalar em Dolanaar."}},
[6722]={"O caminho do caçador",{"Fale com Dazalar em Dolanaar."}},
[6741]={"Mais espólios!",nil},
[6761]={"Uma nova fronteira",{"Volte a Darnassus e fale com Mathrengyl Ursivagus no Enclave Cenariano, em Darnassus."}},
[6762]={"Ravine Saturna",{"Fale com Ravine Saturna no Refúgio Noturno, que fica na Clareira da Lua. A Clareira da Lua fica entre a Selva Maleva e Hibérnia. Uma estrada que sai do Domínio dos Presamatos leva até lá."}},
[6781]={"Mais sobras de armadura",nil},
[6801]={"Lokholar, o Senhor do Gelo",nil},
[6804]={"Água contaminada",{"Use o Aspecto de Neptulon nos elementais contaminados das Terras Pestilentas Orientais. Leve 12 Braçadeiras Dissonantes e o Aspecto de Neptulon ao Duque Hidráxis em Azshara."}},
[6805]={"Tempestades e estrondores",{"Mate 15 Tempestades de Poeira e 15 Estrondores do Deserto e fale novamente com o Duque Hidráxis em Azshara."}},
[6821]={"O Olho do Mirabrasa",{"Leve o Olho do Mirabrasa ao Duque Hidráxis em Azshara."}},
[6822]={"O Núcleo Derretido",{"Mate 1 Senhor do Fogo, 1 Gigante Derretido, 1 Cão-magma Antigo e 1 Irrompedor de Lava e depois fale novamente com o Duque Hidráxis em Azshara."}},
[6823]={"Agente de Hidráxis",{"Alcance a reputação de <Honrado/Honrada> pelos Senhores das Águas Hidraxianos e depois fale com o Duque Hidráxis em Azshara."}},
[6824]={"Mãos do inimigo",{"Leve as Mãos de Lúcifron, Sulfuron, Geena e Shazzrah ao Duque Hidráxis em Azshara."}},
[6825]={"Clamor do Ar – Esquadrilha de Guse",nil},
[6826]={"Clamor do Ar – Esquadrilha de Jeztor",nil},
[6827]={"Clamor do Ar – Esquadrilha de Mulverick",nil},
[6844]={"Umbero, o arquivista",{"Leve o Objeto Silitídeo Incrustado para Umbero, arquivista do Círculo Cenariano, na vila de Refúgio Noturno, na Clareira da Lua."}},
[6845]={"Desvendando segredos do passado",{"Fale com Ravine Saturna no vilarejo de Refúgio Noturno, na Clareira da Lua."}},
[6846]={"Que comece o ataque!",nil},
[6881]={"Ivus, o Senhor da Floresta",nil},
[6921]={"Nas ruínas",{"Leve o Núcleo das Profundezas para Je'neu Sancrea no Assentamento Zoram'gar, no Vale Gris."}},
[6922]={"O Barão Aquanis",{"Leve o Globo d'Água Estranho para Je'neu Sancrea no Assentamento Zoram'gar, no Vale Gris."}},
