[6981]={"A lasca faiscante",{"Viaje para a Vila Catraca e procure alguém que possa contar mais alguma coisa sobre a lasca faiscante.","","Depois, entregue a lasca conforme as orientações."}},
[6982]={"Suprimentos de Dentefrio",{"Leve 10 Suprimentos dos Dentefrio para o Intendente da Aliança em Dun Baldar."}},
[6985]={"Suprimentos dos Ferrofundo",{"Leve 10 Suprimentos dos Ferrofundo para o Intendente da Horda na Bastilha Lobo do Gelo."}},
[7001]={"Estábulos vazios",{"Localize um Lobo do Gelo no Vale Alterac. Use a Focinheira de Lobo do Gelo para \"domar\" a fera. Uma vez domado, o Lobo do Gelo seguirá você até o Mestre dos Estábulos dos Lobo do Gelo. Fale com o Mestre dos Estábulos para conseguir crédito pela captura."}},
[7002]={"Arneses de couro de carneiro",nil},
[7003]={"Querida, encolhi os gigantes",{"Use o Ultra-encolhedor de Zorbin para deixar qualquer tipo de gigante de Feralas com um tamanho mais compacto e manejável. Colete 15 Resíduos de Miniaturização encontrados nos gigantes encolhidos e leve para Zorbin Cegasvista, que fica nas docas da Costa Esquecida, em Feralas."}},
[7026]={"Arneses de cavalgar carneiro",nil},
[7027]={"Estábulos vazios",{"Localize um Carneiro de Alterac, no Vale Alterac. Use a Coleira de Treinamento de Lançatroz no Carneiro de Alterac para \"domar\" a fera. Uma vez domado, o Carneiro de Alterac seguirá você até o Mestre dos Estábulos. Fale com o Mestre dos Estábulos para conseguir crédito pela captura."}},
[7028]={"Raízes do mal",{"Colete 25 Entalhes de Cristal Terádrico para Faia, na Desolação."}},
[7029]={"A corrupção de Torpelíngua",{"Encha a Ampola Cerúlea Tampada na poça de cristal laranja, em Maraudon.","","Use a Ampola Cerúlea Cheia nos Cipós Caule Torpe para forçar os Rebentos Tóxxicos corrompidos a emergir.","","Cure 8 plantas ao matar os Rebentos Tóxxicos, depois fale novamente com Vark Chaga de Guerra, na Aldeia Pescassombra."}},
[7041]={"A corrupção de Torpelíngua",{"Encha a Ampola Cerúlea Tampada na poça de cristal laranja, em Maraudon.","","Use a Ampola Cerúlea Cheia nos Cipós Caule Torpe para forçar os Rebentos Tóxxicos corrompidos a emergir.","","Cure 8 plantas ao matar os Rebentos Tóxxicos, depois fale novamente com Talendria, no Posto do Nijel."}},
[7044]={"Lendas de Maraudon",{"Recupere as duas partes do Cetro de Celebras: o Bastão de Celebras e o Diamante de Celebras.","","Encontre um jeito de falar com Celebras."}},
[7046]={"O Cetro de Celebras",{"Ajude Celebras, o Redimido, a criar o Cetro de Celebras.","","Fale com ele quando o ritual estiver concluído."}},
[7064]={"Corrupção da terra e dos grãos",{"Mate a Princesa Theradras e fale novamente com Selendra perto da Aldeia Pescassombra, na Desolação."}},
[7065]={"Corrupção da terra e dos grãos",{"Mate a Princesa Theradras e fale novamente com o Guardião Marandis no Posto do Nijel, na Desolação."}},
[7066]={"A semente da vida",{"Procure Remulos, na Clareira da Lua, e entregue a ele a Semente da Vida."}},
[7067]={"As instruções do pária",{"Leia as Instruções do Pária. Depois, obtenha em Maraudon o Amuleto da União e devolva-o ao Centauro Pária, na parte sul de Desolação."}},
[7068]={"Fragmentos de lascanegra",{"Colete 10 Fragmentos de Lascanegra em Maraudon e leve-os para Uthel'nay, em Orgrimmar."}},
[7070]={"Fragmentos de lascanegra",{"Colete 10 Fragmentos de Lascanegra em Maraudon e leve-os para o Arquimago Tervosh, em Theramore, na costa do Pântano Vadeoso."}},
[7081]={"Cemitérios do Vale Alterac",{"Ataque um cemitério e, então, apresente-se ao Sargento Durgen Lançatroz nas Montanhas de Alterac."}},
[7082]={"Os cemitérios de Alterac",{"Ataque um cemitério e depois apresente-se à Cabo Tika Rosnassangue nas Montanhas de Alterac."}},
[7101]={"Torres e Casamatas",{"Capture uma casamata inimiga e então apresente-se à Cabo Tika Rosnassangue nas Montanhas de Alterac."}},
[7102]={"Torres e Casamatas",{"Destrua o estandarte em uma torre ou casamata inimiga, e então fale novamente com o Sargento Durgen Lançatroz nas Montanhas de Alterac."}},
[7121]={"O Intendente",{"Fale com o Intendente dos Lançatroz."}},
[7122]={"Capture uma mina",{"Capture uma mina não controlada pelos Lançatroz e, a seguir, apresente-se ao Sargento Durgen Lançatroz nas Montanhas de Alterac."}},
[7123]={"Fale com nosso Intendente",{"Fale com o Intendente dos Lobo do Gelo."}},
[7124]={"Capture uma mina",{"Capture uma mina e, a seguir, apresente-se à Cabo Tika Rosnassangue nas Montanhas de Alterac."}},
[7141]={"A Batalha de Alterac",{"Siga para o Vale Alterac, derrote Drek'thar, o general da Horda, e volte a falar com o Prospector Entalharrocha nas Montanhas de Alterac."}},
[7142]={"A Batalha por Alterac",{"Siga para o Vale Alterac, derrote Vanndar Lançatroz, o general anão, e fale novamente com Voggah Garramort, nas Montanhas de Alterac."}},
[7161]={"Campo de testes",{"Vá até a caverna dos Garragreste, a sudeste da base principal no Vale Alterac, e encontre o Estandarte dos Lobo do Gelo. Entregue o Estandarte dos Lobo do Gelo para o Mestre Guerreiro Laggrond."}},
[7162]={"Campo de testes",{"Viaje para a Caverna Asálgida a sudoeste de Dun Baldar, no Vale Alterac, e recupere o Estandarte dos Lançatroz. Entregue o Estandarte dos Lançatroz para o Tenente Haggerdin nas Montanhas de Alterac."}},
