[8413]={"O Vodu",{"Leve as Penas Vodu para Bath'rah, o Vigia dos Ventos."}},
[8414]={"Dissipando o mal",{"Colete 20 Pedras do Flagelo do Lacaio e leve-as ao Sumo Sacerdote Thel'danis nas Terras Pestilentas Ocidentais."}},
[8415]={"Morro do Ventogelante",{"Fale com o Comandante Ashlam Punhobom no Morro do Ventogelante."}},
[8416]={"Pedras do Flagelo inertes",{"Leve a Pedra do Flagelo Inerte ao Comandante Ashlam Punhobom no Morro do Ventogelante."}},
[8417]={"Um espírito atormentado",{"Fale com o Herói Caído da Horda na entrada da Barreira do Inferno."}},
[8418]={"Forjando o megalito",{"Leve as Penas Vodu para Ashlam Punhobom."}},
[8419]={"Pedido de diabrete",{"Leve um pedaço de Tecido Vil para Diabretim, em Selva Maleva."}},
[8420]={"Quente e pinicante",{"Leve um pedaço de Tecido Vil para Diabretim, em Selva Maleva."}},
[8421]={"O enchimento errado",{"Leve 10 pedaços de Madeira Podre e 4 Essências de Peçonha para Diabretim em Selva Maleva."}},
[8422]={"Penas de troll",{"Leve um total de 6 Penas Vodu dos trolls do templo submerso."}},
[8423]={"Parentesco guerreiro",{"Mate 7 Javiltuscos na Barreira do Inferno e fale novamente com o Herói Caído da Horda."}},
[8424]={"Guerra aos devotos da sombra",{"Mate os Devotos da Sombra na Barreira do Inferno e fale novamente com o Herói Caído da Horda."}},
