[9248]={"Uma humilde oferenda",{"Aurel Folháurea, do Forte Cenariano, em Silithus, quer que você leve para ela 1 Cetro Abissal. Você também precisa ser Honrado pelo Círculo Cenariano."}},
[9250]={"Cajado de Atiesh",{"Encontre alguém que ajude você a recuperar as duas últimas peças e a livrar o cajado do mal."}},
[9251]={"Atiesh, o grande cajado conspurcado",{"Anacronos, nas Cavernas do Tempo, em Tanaris, quer a Ponta do cajado de Atiesh e a Base de Atiesh."}},
[9257]={"Atiesh, Grande Cajado do Guardião",{"Anacronos, nas Cavernas do Tempo, em Tanaris, quer que você leve Atiesh, Grande Cajado do Guardião, a Stratholme para usá-lo no Solo Consagrado. Em seguida, derrote a entidade exorcizada do cajado e fale novamente com o dragão."}},
[9259]={"Um duas-caras na Vela Sangrenta",nil},
[9266]={"Fazendo as pazes",nil},
[9267]={"Curando velhas feridas",nil},
[9268]={"Guerra no mar",nil},
[9272]={"Vestindo a tripulação",nil},
[9338]={"Lealdade ao Círculo Cenariano",nil},
[9362]={"Senhor da Guerra Krellian",{"Recupere a Concha Prismática para o Arquimago Tauriel. O Arquimago reside numa torre no topo dos penhascos de Azshara."}},
[9364]={"Magia fragmentada",{"Polimorfe as Iraliscas de Azshara e mate os clones que aparecerem. Quando matar 50 Clones Polimorfados, volte e fale com o Arquimago Tauriel, em Azshara."}},
[9415]={"Apresente-se ao Marechal Murazul",{"Fale com Marechal Murazul no acampamento da Aliança, perto da Colme'Zora."}},
[9416]={"Apresente-se à General Kyríala",{"Fale com a General Kyríala no acampamento da Horda, perto da Colme'Régia."}},
[9419]={"Limpeza do deserto",{"Encontre e leve a Silitista até o Extrator de Silitista, então fale com o Marechal Murazul no acampamento da Aliança perto da Colme'Zora."}},
[9422]={"Limpeza do deserto",{"Encontre e leve a Silitista até o Extrator de Silitista, então fale com a General Kyríala, no acampamento da Horda perto da Colme'Régia."}},
[9664]={"Novos postos avançados",{"Capture a Torre da Coroa, a Torre da Muralha Leste, a Torre do Passo Norte e a Torre do Bosque Pestilento, nas Terras Pestilentas Orientais, depois fale novamente com o Emissário Barbabranca, na Capela Esperança da Luz."}},
[9665]={"Reforçando nossas defesas",{"Capture a Torre da Coroa, a Torre da Muralha Leste, a Torre do Passo Norte e a Torre do Bosque Pestilento, nas Terras Pestilentas Orientais, depois fale novamente com o Emissário Gormok, na Capela Esperança da Luz."}},
[65593]={"Corações dos amantes",{"Leve os corações de Avelina Lily e Isaac Pessoa para Silvério Hidalgo no Templo dos Malditos."}},
[65597]={"A vinculação",{"Usando os Corações dos Amantes, evoque e subjugue um íncubo. Depois, devolva os Corações dos Amantes para Silvério Hidalgo no Distrito da Magia na Cidade Baixa."}},
[65601]={"O amor machuca",{"Fale com Magar em Orgrimmar."}},
[65602]={"Amar é...",{"Obtenha a Estatueta de Madeira e leve para Gakin, o Neromante, no Distrito dos Magos de Ventobravo."}},
[65603]={"A vinculação",{"Usando a Estatueta de Madeira, evoque e subjugue um íncubo. Depois, devolva a Estatueta de Madeira para Gakin, o Neromante, no Cordeiro Imolado."}},
[65604]={"A vinculação",{"Usando o Lenço Fenecido, evoque e subjugue um íncubo. Depois, devolva o Lenço Fenecido para Gan'rul Olho de Sangue em Orgrimmar."}},
[65610]={"A esperança é a última que morre",{"Investigue o Lago Céu Caído, que fica no Vale Gris, e relate suas descobertas a Gan'rul Olho de Sangue em Orgrimmar."}},
}]=])())
