[26656]={name="Tanque de Batalha Qiraji Preto",lore="Ainda hoje é possível encontrar uma grande variedade de Tanques de Batalha Qiraji nas ruínas de Ahn'Qiraj, porém os espécimes mais escuros só foram vistos no dia em que soou o gongo do Escaravelho."},
[470]={name="Garanhão Preto",lore="Dizem os boatos que é o cavalo favorito da AVIN para as missões noturnas devido ao seu pelo negro.",vendor="Carina Caçador"},
[22718]={name="Kodo de Guerra Preto",lore="Os Kor'kron gostam dos kodos de guerra pelo seu comportamento agressivo e imprevisível. Quando soa o chamado do Kodo de Guerra Preto, é sinal de que o sangue vai ser derramado.",vendor="Saqueador Bork"},
[22720]={name="Carneiro de Guerra Preto",lore="Os anões valorizam seus companheiros carneiros por entrarem na batalha sem medo.",vendor="Tenente Karter"},
[22721]={name="Raptor de Guerra Preto",lore="Raptores da mesma linhagem cruel de Ohgan, responsável por levar o Império Gurubashi à vitória.",vendor="Saqueador Bork"},
[22717]={name="Corcel de Guerra Preto",lore="Adestrado para enfrentar combates corpo a corpo brutais nos mais violentos campos de batalha.",vendor="Tenente Karter"},
[22723]={name="Tigre de Guerra Preto",lore="Assim como seus primos sabres-da-noite, os tigres são conhecidos pelas garras afiadíssimas, pela agilidade inacreditável e por adorarem um carinho atrás da orelha.",vendor="Tenente Karter"},
[22724]={name="Lobo de Guerra Preto",lore="Admirados pelos guardas de Orgrimmar graças a seu olfato apuradíssimo.",vendor="Saqueador Bork"},
[10969]={name="Mecanostruz Azul",lore="\"Os exográficos terradinâmicos são enviados aos reguladores do equilíbrio pelo sistema de projeção hidráulica...\" - Binjy Penapita",vendor="Milli Penapita"},
[25953]={name="Tanque de Batalha Qiraji Azul",lore="Este silitídeo (relativamente) domesticado só se sente à vontade nos desertos de Ahn'Qiraj."},
[17463]={name="Cavalo Descarnado Azul",lore="Os Renegados acreditam que até mesmo as bestas de carga ficam atormentadas se não tiverem um propósito na morte-viva.",vendor="Zacarias Pústulo"},
[458]={name="Cavalo Castanho",lore="Um dos favoritos dos guardas de Ventobravo por causa da sua paciência e do seu vigor.",vendor="Carina Caçador"},
[18990]={name="Kodo Marrom",lore="\"Os kodos são a espinha dorsal do nosso povo. Aonde quer que a Horda vá, seja para comerciar, habitar ou guerrear, lá estão os poderosos kodos.\" - Harb Casco Afiado",vendor="Harb Casco Afiado"},
[6899]={name="Carneiro Marrom",lore="Os carneiros batem a cabeça uns contra os outros por horas a fio para impressionar a fêmea. De certa forma, são bem parecidos com os anões.",vendor="Veron Ambarmanso"},
[17464]={name="Cavalo Descarnado Castanho",lore="Os Renegados acreditam que até mesmo as bestas de carga ficam atormentadas se não tiverem um propósito na morte-viva.",vendor="Zacarias Pústulo"},
